int adpcm_enc_sin( int rad )
{
  int diff;
  int app = 0;
  int inc = 1;
  int m;

  /* The two range-reduction loops in closed form (k steps of 2 * PI). */
  if ( rad > 2 * PI )
    rad -= ( ( rad - 1 ) / ( 2 * PI ) ) * ( 2 * PI );
  if ( rad < -2 * PI )
    rad += ( ( -rad - 1 ) / ( 2 * PI ) ) * ( 2 * PI );

  /* The series term product wraps in 32 bits (the original's behaviour). */
  m = -( rad * rad );
  diff = rad;
  app = diff;
  diff = adpcm_enc_div( ( int )( ( unsigned )diff * ( unsigned )m ), ( 2 * inc ) * ( 2 * inc + 1 ) );
  app = app + diff;
  inc++;

  /* |diff| >= 1 <=> diff != 0: after the first step |diff| <= 2^31 / 6. */
  while ( diff != 0 ) {
    diff = adpcm_enc_div( ( int )( ( unsigned )diff * ( unsigned )m ), ( 2 * inc ) * ( 2 * inc + 1 ) );
    app = ( int )( ( unsigned )app + ( unsigned )diff );
    inc++;
  }

  return app;
}
