int binarysearch_binary_search( int x )
{
  /* Keys are strictly increasing: a branch-free lower bound (czero picks the
     half) followed by one equality check gives the same answer. */
  long base = 0, n = binarysearch_N;
  while ( n > 1 ) {
    long half = n >> 1;
    base = zc_sel( binarysearch_data[ base + half ].key <= x, base + half, base );
    n -= half;
  }
  return ( int )zc_sel( binarysearch_data[ base ].key == x, binarysearch_data[ base ].value, -1 );
}

void _Pragma( "entrypoint" ) binarysearch_main( void )
{
  /* Four branch-free searches run interleaved so their load chains overlap;
     the keys are drawn in the same order as the original loop. */
  int i, k, sum = 0;
  for ( i = 0; i < 4096; i += 4 ) {
    long x[ 4 ], base[ 4 ] = { 0, 0, 0, 0 }, n = binarysearch_N;
    for ( k = 0; k < 4; k++ )
      x[ k ] = binarysearch_randomInteger() & 0x3fff;
    while ( n > 1 ) {
      long half = n >> 1;
      for ( k = 0; k < 4; k++ )
        base[ k ] = zc_sel( binarysearch_data[ base[ k ] + half ].key <= x[ k ], base[ k ] + half, base[ k ] );
      n -= half;
    }
    for ( k = 0; k < 4; k++ )
      sum += ( int )zc_sel( binarysearch_data[ base[ k ] ].key == x[ k ], binarysearch_data[ base[ k ] ].value, -1 );
  }
  binarysearch_result = sum;
}

