  int *a = bitonic_a;
  for ( int k = 2; k <= bitonic_N; k <<= 1 )
    for ( int j = k >> 1; j > 0; j >>= 1 )
      for ( int b = 0; b < bitonic_N; b += 2 * j ) {
        long up = ( b & k ) == 0;
        int *p = a + b, *q = a + b + j;
        for ( int i = 0; i < j; i++ ) {
          long x = p[ i ], y = q[ i ];
          long s = up == ( x > y );
          p[ i ] = ( int )zc_sel( s, y, x );
          q[ i ] = ( int )zc_sel( s, x, y );
