int bsort_Initialize( int Array[] )
{
  unsigned seed = 1;
  int Index;
  for ( Index = 0; Index < bsort_SIZE; Index ++ ) {
    seed = seed * 1103515245u + 12345u;
    Array[ Index ] = ( int )( seed >> 16 ) & 0x7fff;
  }
