int bsort_return( void )
{
  int Index, sum = 0;
  for ( Index = 0; Index < bsort_SIZE - 1; Index ++ )
    sum += ( bsort_Array[ Index ] <= bsort_Array[ Index + 1 ] ) * ( Index & 7 ) + bsort_Array[ Index ];
  return sum;
}

int bsort_BubbleSort( int Array[] )
{
  int i, Index;
  for ( i = 0; i < bsort_SIZE - 1; i ++ ) {
    long Swapped = 0;
    int lim = bsort_SIZE - i;
    long cur = Array[ 0 ];
    /* Carry the running maximum in a register; czero picks min/max. */
    for ( Index = 0; Index < bsort_SIZE - 1 && Index <= lim; Index ++ ) {
      long next = Array[ Index + 1 ];
      long gt = cur > next;
      Array[ Index ] = ( int )zc_sel( gt, next, cur );
      cur = zc_sel( gt, cur, next );
      Swapped |= gt;
    }
    Array[ Index ] = ( int )cur;
    if ( !Swapped )
      break;
  }
  return 0;
}

void _Pragma( "entrypoint" ) bsort_main( void )
{
  bsort_BubbleSort( bsort_Array );
}

