/* 8x8 signed-char block as eight 64-bit rows (byte j of row i = element [i][j]).
   dst[ j*8+i ] = +/- src[ i*8+j ]: per-byte sign flips are applied to the source
   rows first (mask m_even for even rows, m_odd for odd rows; 0xFF byte = negate),
   then the block is transposed in registers. Even destination rows are stored
   only if write_even (odd rows always). */
typedef unsigned long __attribute__( ( may_alias ) ) cjt_u64;

static inline __attribute__( ( always_inline ) ) unsigned long
cjt_cneg( unsigned long x, unsigned long m )
{
  if ( m == 0 )
    return x;
  unsigned long y = x ^ m;
  return ( ( y & 0x7F7F7F7F7F7F7F7FUL ) + ( m & 0x0101010101010101UL ) ) ^
         ( y & 0x8080808080808080UL );
}

#define CJT_SWP( a, b, sh, mask ) \
  { unsigned long t_ = ( ( a >> sh ) ^ b ) & mask; b ^= t_; a ^= t_ << sh; }

static inline __attribute__( ( always_inline ) ) void
cjt_block( signed char *d, const signed char *s, unsigned long m_even,
           unsigned long m_odd, int write_even )
{
  const cjt_u64 *q = ( const cjt_u64 * )s;
  cjt_u64 *o = ( cjt_u64 * )d;
  unsigned long r0 = cjt_cneg( q[ 0 ], m_even ), r1 = cjt_cneg( q[ 1 ], m_odd );
  unsigned long r2 = cjt_cneg( q[ 2 ], m_even ), r3 = cjt_cneg( q[ 3 ], m_odd );
  unsigned long r4 = cjt_cneg( q[ 4 ], m_even ), r5 = cjt_cneg( q[ 5 ], m_odd );
  unsigned long r6 = cjt_cneg( q[ 6 ], m_even ), r7 = cjt_cneg( q[ 7 ], m_odd );
  CJT_SWP( r0, r1, 8, 0x00FF00FF00FF00FFUL ) CJT_SWP( r2, r3, 8, 0x00FF00FF00FF00FFUL )
  CJT_SWP( r4, r5, 8, 0x00FF00FF00FF00FFUL ) CJT_SWP( r6, r7, 8, 0x00FF00FF00FF00FFUL )
  CJT_SWP( r0, r2, 16, 0x0000FFFF0000FFFFUL ) CJT_SWP( r1, r3, 16, 0x0000FFFF0000FFFFUL )
  CJT_SWP( r4, r6, 16, 0x0000FFFF0000FFFFUL ) CJT_SWP( r5, r7, 16, 0x0000FFFF0000FFFFUL )
  CJT_SWP( r0, r4, 32, 0x00000000FFFFFFFFUL ) CJT_SWP( r1, r5, 32, 0x00000000FFFFFFFFUL )
  CJT_SWP( r2, r6, 32, 0x00000000FFFFFFFFUL ) CJT_SWP( r3, r7, 32, 0x00000000FFFFFFFFUL )
  if ( write_even ) {
    o[ 0 ] = r0; o[ 2 ] = r2; o[ 4 ] = r4; o[ 6 ] = r6;
  }
  o[ 1 ] = r1; o[ 3 ] = r3; o[ 5 ] = r5; o[ 7 ] = r7;
}
#define CJT_ODD 0xFF00FF00FF00FF00UL
#define CJT_EVEN 0x00FF00FF00FF00FFUL

