void cjpeg_transupp_do_flip_v( j_compress_ptr dstinfo )
{
  unsigned int MCU_rows, comp_height, dst_blk_x, dst_blk_y;
  int ci, i, j, offset_y;
  JCOEFPTR src_ptr, dst_ptr;

  MCU_rows = dstinfo->image_height / ( dstinfo->max_v_samp_factor * DCTSIZE );

  int compptr_v_samp_factor = 8;
  unsigned int compptr_height_in_blocks = 19;
  unsigned int compptr_width_in_blocks = 29;

  _Pragma( "loopbound min 3 max 3" )
  for ( ci = 0; ci < dstinfo->num_components;
        ci++, compptr_v_samp_factor = 1, compptr_width_in_blocks = 15 ) {
    comp_height = MCU_rows * compptr_v_samp_factor;

    compptr_height_in_blocks = 10;
    _Pragma( "loopbound min 2 max 10" )
    for ( dst_blk_y = 0; dst_blk_y < compptr_height_in_blocks;
          dst_blk_y += compptr_v_samp_factor ) {

      _Pragma( "loopbound min 1 max 8" )
      for ( offset_y = 0; offset_y < compptr_v_samp_factor; offset_y++ ) {
        if ( dst_blk_y < comp_height ) {

          _Pragma( "loopbound min 15 max 29" )
          for ( dst_blk_x = 0; dst_blk_x < compptr_width_in_blocks;
                dst_blk_x++ ) {

            src_ptr = cjpeg_transupp_input;
            dst_ptr = cjpeg_transupp_output_data;

            _Pragma( "loopbound min 4 max 4" )
            for ( i = 0; i < DCTSIZE; i += 2 ) {

              j = 0;
              _Pragma( "loopbound min 8 max 8" )
              do {
                if ( dst_blk_x < comp_height )
                  *dst_ptr++ = *src_ptr++;
                j++;
              } while ( j < DCTSIZE );

              j = 0;
              _Pragma( "loopbound min 8 max 8" )
              do {
                if ( dst_blk_x < comp_height )
                  *dst_ptr++ = - *src_ptr++;
                j++;
              } while ( j < DCTSIZE );
            }
          }
        }
      }
    }
  }
}

void cjpeg_transupp_do_rot_90( j_compress_ptr dstinfo )
{
  unsigned int MCU_cols, comp_width, dst_blk_x, dst_blk_y;
  int ci, i, j, offset_x, offset_y;
  JCOEFPTR src_ptr, dst_ptr;

  MCU_cols = dstinfo->image_width / ( dstinfo->max_h_samp_factor * DCTSIZE );

  int compptr_h_samp_factor = 2;
  int compptr_v_samp_factor = 8;
  unsigned int compptr_height_in_blocks = 29;
  unsigned int compptr_width_in_blocks = 19;

  _Pragma( "loopbound min 3 max 3" )
  for ( ci = 0; ci < dstinfo->num_components;
        ci++, compptr_h_samp_factor = compptr_v_samp_factor = 1,
        compptr_height_in_blocks = 15, compptr_width_in_blocks = 10 ) {

    comp_width = MCU_cols * compptr_h_samp_factor;

    _Pragma( "loopbound min 4 max 15" )
    for ( dst_blk_y = 0; dst_blk_y < compptr_height_in_blocks;
          dst_blk_y += compptr_v_samp_factor ) {

      offset_y = 0;
      _Pragma( "loopbound min 1 max 8" )
      for ( ; offset_y < compptr_v_samp_factor; offset_y++ ) {
        dst_blk_x = 0;
        _Pragma( "loopbound min 10 max 10" )
        for ( ; dst_blk_x < compptr_width_in_blocks;
              dst_blk_x += compptr_h_samp_factor ) {

          offset_x = 0;
          _Pragma( "loopbound min 1 max 2" )
          for ( ; offset_x < compptr_h_samp_factor; offset_x++ ) {

            src_ptr = cjpeg_transupp_input2;

            if ( dst_blk_x < comp_width ) {

              /* odd source rows negated, then transposed */
              cjt_block( cjpeg_transupp_output_data2, src_ptr, 0, ~0UL, 1 );
            } else {

              dst_ptr = cjpeg_transupp_output_data2;

              _Pragma( "loopbound min 8 max 8" )
              for ( i = 0; i < DCTSIZE; i++ )
                j = 0;
              _Pragma( "loopbound min 8 max 8" )
              for ( ; j < DCTSIZE; j++ ) {
                if ( dst_blk_y < comp_width )
                  dst_ptr[ j * DCTSIZE + i ] = src_ptr[ i * DCTSIZE + j ];
              }
            }
          }
        }
      }
    }
  }
}

void cjpeg_transupp_do_rot_270( j_compress_ptr dstinfo )
{
  unsigned int MCU_rows, comp_height, dst_blk_x, dst_blk_y;
  int ci, i, j, offset_x, offset_y;
  JCOEFPTR src_ptr, dst_ptr;

  MCU_rows = dstinfo->image_height / ( dstinfo->max_v_samp_factor * DCTSIZE );

  int compptr_h_samp_factor = 2;
  int compptr_v_samp_factor = 8;
  unsigned int compptr_height_in_blocks = 29;
  unsigned int compptr_width_in_blocks = 19;

  _Pragma( "loopbound min 3 max 3" )
  for ( ci = 0; ci < dstinfo->num_components;
        ci++, compptr_h_samp_factor = compptr_v_samp_factor = 1,
        compptr_height_in_blocks = 15, compptr_width_in_blocks = 10 ) {

    comp_height = MCU_rows * compptr_v_samp_factor;

    _Pragma( "loopbound min 4 max 15" )
    for ( dst_blk_y = 0; dst_blk_y < compptr_height_in_blocks;
          dst_blk_y += compptr_v_samp_factor ) {

      offset_y = 0;
      _Pragma( "loopbound min 1 max 8" )
      for ( ; offset_y < compptr_v_samp_factor; offset_y++ ) {
        dst_blk_x = 0;
        _Pragma( "loopbound min 10 max 10" )
        for ( ; dst_blk_x < compptr_width_in_blocks;
              dst_blk_x += compptr_h_samp_factor ) {

          offset_x = 0;
          _Pragma( "loopbound min 1 max 2" )
          for ( ; offset_x < compptr_h_samp_factor; offset_x++ ) {

            dst_ptr = cjpeg_transupp_output_data3;

            if ( dst_blk_y < comp_height ) {

              src_ptr = cjpeg_transupp_input3;

              /* odd destination rows (odd source columns) negated */
              cjt_block( dst_ptr, src_ptr, CJT_ODD, CJT_ODD, 1 );
            } else {

              src_ptr = cjpeg_transupp_input3_2;

              _Pragma( "loopbound min 8 max 8" )
              for ( i = 0; i < DCTSIZE; i++ )
                j = 0;
              _Pragma( "loopbound min 8 max 8" )
              for ( ; j < DCTSIZE; j++ ) {
                if ( dst_blk_y < comp_height )
                  dst_ptr[ j * DCTSIZE + i ] = src_ptr[ i * DCTSIZE + j ];
              }
            }
          }
        }
      }
    }
  }
}

void cjpeg_transupp_do_rot_180( j_compress_ptr dstinfo )
{
  unsigned int MCU_cols, MCU_rows, comp_width, comp_height, dst_blk_x,
           dst_blk_y;
  int ci, i, j, offset_y;
  JCOEFPTR src_ptr, dst_ptr;

  int compptr_h_samp_factor = 2;
  int compptr_v_samp_factor = 8;
  unsigned int compptr_width_in_blocks = 29;
  unsigned int compptr_height_in_blocks = 19;

  MCU_cols = dstinfo->image_width / ( dstinfo->max_h_samp_factor * DCTSIZE );
  MCU_rows = dstinfo->image_height / ( dstinfo->max_v_samp_factor * DCTSIZE );

  _Pragma( "loopbound min 3 max 3" )
  for ( ci = 0; ci < dstinfo->num_components; ci++,
        compptr_h_samp_factor = compptr_v_samp_factor = 1,
        compptr_width_in_blocks  = 15, compptr_height_in_blocks = 10 ) {

    comp_width  = MCU_cols * compptr_h_samp_factor;
    comp_height = MCU_rows * compptr_v_samp_factor;

    _Pragma( "loopbound min 3 max 10" )
    for ( dst_blk_y = 0; dst_blk_y < compptr_height_in_blocks;
          dst_blk_y += compptr_v_samp_factor ) {
      offset_y = 0;
      _Pragma( "loopbound min 1 max 8" )
      for ( ; offset_y < compptr_v_samp_factor; offset_y++ ) {
        if ( dst_blk_y < comp_height ) {

          _Pragma( "loopbound min 14 max 28" )
          for ( dst_blk_x = 0; dst_blk_x < comp_width; dst_blk_x++ ) {
            dst_ptr = cjpeg_transupp_output_data4;
            src_ptr = cjpeg_transupp_input4;

            _Pragma( "loopbound min 4 max 4" )
            for ( i = 0; i < DCTSIZE; i += 2 ) {
              j = 0;

              _Pragma( "loopbound min 4 max 4" )
              for ( ; j < DCTSIZE; j += 2 ) {
                if ( dst_blk_x < comp_height ) {
                  *dst_ptr++ = *src_ptr++;
                  *dst_ptr++ = - *src_ptr++;
                }
              }

              j = 0;

              _Pragma( "loopbound min 4 max 4" )
              for ( ; j < DCTSIZE; j += 2 ) {
                if ( dst_blk_x < comp_height ) {
                  *dst_ptr++ = - *src_ptr++;
                  *dst_ptr++ = *src_ptr++;
                }
              }
            }
          }

          _Pragma( "loopbound min 1 max 1" )
          for ( ; dst_blk_x < compptr_width_in_blocks; dst_blk_x++ ) {

            dst_ptr = cjpeg_transupp_output_data4;
            src_ptr = cjpeg_transupp_input4;
            _Pragma( "loopbound min 4 max 4" )
            for ( i = 0; i < DCTSIZE; i += 2 ) {
              j = 0;
              _Pragma( "loopbound min 8 max 8" )
              for ( ; j < DCTSIZE; j++ )
                *dst_ptr++ = *src_ptr++;
              j = 0;
              _Pragma( "loopbound min 8 max 8" )
              for ( ; j < DCTSIZE; j++ )
                *dst_ptr++ = - *src_ptr++;
            }
          }
        } else {

          dst_blk_x = 0;

          _Pragma( "loopbound min 14 max 14" )
          do {
            dst_ptr = cjpeg_transupp_output_data4;
            src_ptr = cjpeg_transupp_input4;

            i = 0;
            _Pragma( "loopbound min 32 max 32" )
            while ( i < DCTSIZE2 ) {
              *dst_ptr++ = *src_ptr++;
              *dst_ptr++ = - *src_ptr++;
              i += 2;
              dst_ptr += 0;
            }
            dst_blk_x++;
            dst_ptr += 0;
          } while ( dst_blk_x < comp_width );

          _Pragma( "loopbound min 1 max 1" )
          for ( ; dst_blk_x < compptr_width_in_blocks; dst_blk_x++ ) {

            dst_ptr = cjpeg_transupp_output_data4;
            src_ptr = cjpeg_transupp_input4;
            _Pragma( "loopbound min 1 max 1" )
            do {
              *dst_ptr++ = *src_ptr++;
              i++;
            } while ( i < DCTSIZE2 );
          }
        }
      }
    }
  }
}

void cjpeg_transupp_do_transverse( j_compress_ptr dstinfo )
{
  unsigned int MCU_cols, MCU_rows, comp_width, comp_height, dst_blk_x,
           dst_blk_y;
  int ci, i, j, offset_x, offset_y;
  JCOEFPTR src_ptr, dst_ptr;

  int compptr_h_samp_factor = 2;
  int compptr_v_samp_factor = 8;
  unsigned int compptr_height_in_blocks = 29;
  unsigned int compptr_width_in_blocks = 19;

  MCU_cols = dstinfo->image_width / ( dstinfo->max_h_samp_factor * DCTSIZE );
  MCU_rows = dstinfo->image_height / ( dstinfo->max_v_samp_factor * DCTSIZE );

  _Pragma( "loopbound min 3 max 3" )
  for ( ci = 0; ci < dstinfo->num_components; ci++,
        compptr_h_samp_factor = compptr_v_samp_factor = 1,
        compptr_height_in_blocks = 15, compptr_width_in_blocks  = 10 ) {

    comp_width  = MCU_cols * compptr_h_samp_factor;
    comp_height = MCU_rows * compptr_v_samp_factor;

    _Pragma( "loopbound min 4 max 15" )
    for ( dst_blk_y = 0; dst_blk_y < compptr_height_in_blocks;
          dst_blk_y += compptr_v_samp_factor ) {
      offset_y = 0;
      _Pragma( "loopbound min 1 max 8" )
      do {
        dst_blk_x = 0;
        _Pragma( "loopbound min 5 max 10" )
        do {
          offset_x = 0;
          _Pragma( "loopbound min 1 max 2" )
          for ( ; offset_x < compptr_h_samp_factor; offset_x++ ) {

            if ( dst_blk_y < comp_height ) {
              src_ptr = cjpeg_transupp_input5;

              if ( dst_blk_x < comp_width ) {

                /* sign (-1)^(i+j); even dst rows only if dst_blk_y < comp_width */
                cjt_block( cjpeg_transupp_output_data5, src_ptr, CJT_ODD, CJT_EVEN,
                           dst_blk_y < comp_width );
              } else {

                /* odd dst rows negated; even dst rows only if dst_blk_y < comp_width */
                cjt_block( cjpeg_transupp_output_data5, src_ptr, CJT_ODD, CJT_ODD,
                           dst_blk_y < comp_width );
              }
            } else {
              src_ptr = cjpeg_transupp_input5_2;

              if ( dst_blk_x < comp_width ) {

                cjt_block( cjpeg_transupp_output_data5, src_ptr, 0, ~0UL, 1 );
              } else {

                cjt_block( cjpeg_transupp_output_data5, src_ptr, 0, 0, 1 );
              }
            }
            dst_blk_x += compptr_h_samp_factor;
          }
        } while ( dst_blk_x < compptr_width_in_blocks );
        offset_y++;
      } while ( offset_y < compptr_v_samp_factor );
    }
  }
}

void _Pragma ( "entrypoint" ) cjpeg_transupp_main( void )
{
  cjpeg_transupp_dstinfo.image_width = 227;
  cjpeg_transupp_dstinfo.image_height = 149;

  cjpeg_transupp_do_flip_v( &cjpeg_transupp_dstinfo );

  cjpeg_transupp_dstinfo.image_width = 149;
  cjpeg_transupp_dstinfo.image_height = 227;

  cjpeg_transupp_do_rot_90( &cjpeg_transupp_dstinfo );
  cjpeg_transupp_do_rot_270( &cjpeg_transupp_dstinfo );

  cjpeg_transupp_dstinfo.image_width = 227;
  cjpeg_transupp_dstinfo.image_height = 149;

  cjpeg_transupp_do_rot_180( &cjpeg_transupp_dstinfo );

  cjpeg_transupp_dstinfo.image_width = 149;
  cjpeg_transupp_dstinfo.image_height = 227;

  cjpeg_transupp_do_transverse( &cjpeg_transupp_dstinfo );
}

/* Zicond select: c ? a : b, branch-free. */
static inline long zc_sel(long c, long a, long b)
{
  long t, f;
  __asm__("czero.eqz %0, %1, %2" : "=r"(t) : "r"(a), "r"(c));
  __asm__("czero.nez %0, %1, %2" : "=r"(f) : "r"(b), "r"(c));
  return t | f;
}
#define MAXSIZE 256

typedef int matrix [ MAXSIZE ][ MAXSIZE ];

void countnegative_initSeed( void );
int countnegative_randomInteger( void );
void countnegative_initialize( matrix );
void countnegative_init( void );
int countnegative_return( void );
void countnegative_sum( matrix );
void countnegative_main( void );


volatile int countnegative_seed;
matrix countnegative_array;
int countnegative_postotal, countnegative_negtotal;
int countnegative_poscnt, countnegative_negcnt;

void countnegative_initSeed ( void )
{
  countnegative_seed = 0;
}

int countnegative_randomInteger( void )
{
  countnegative_seed = countnegative_seed * 1103515245u + 12345u;
  return ( int )( ( ( unsigned )countnegative_seed >> 16 ) & 0x1fff ) - 4096;
}

void countnegative_initialize( matrix Array )
{
  register int OuterIndex, InnerIndex;

  _Pragma( "loopbound min 20 max 20" )
  for ( OuterIndex = 0; OuterIndex < MAXSIZE; OuterIndex++ )
    _Pragma( "loopbound min 20 max 20" )
    for ( InnerIndex = 0; InnerIndex < MAXSIZE; InnerIndex++ )
      Array[ OuterIndex ][ InnerIndex ] =  countnegative_randomInteger();
}

void countnegative_init( void )
{
  countnegative_initSeed();
  countnegative_initialize( countnegative_array );
}

int countnegative_return( void )
{
  return countnegative_postotal + countnegative_poscnt + countnegative_negtotal + countnegative_negcnt;
}

void countnegative_sum( matrix Array )
{
  long Ptotal = 0, Ntotal = 0, Ncnt = 0;
  for ( int Outer = 0; Outer < MAXSIZE; Outer++ )
    for ( int Inner = 0; Inner < MAXSIZE; Inner++ ) {
      long v = Array[ Outer ][ Inner ];
      long neg = v < 0;
      long p, n;
      __asm__( "czero.nez %0, %1, %2" : "=r"( p ) : "r"( v ), "r"( neg ) );
      __asm__( "czero.eqz %0, %1, %2" : "=r"( n ) : "r"( v ), "r"( neg ) );
      Ptotal += p;
      Ntotal += n;
      Ncnt += neg;
    }
  countnegative_postotal = Ptotal;
  countnegative_poscnt = MAXSIZE * MAXSIZE - Ncnt;
  countnegative_negtotal = Ntotal;
  countnegative_negcnt = Ncnt;
}

void _Pragma( "entrypoint" ) countnegative_main ( void )
{
  countnegative_sum(  countnegative_array );
}

#include "input.h"

#define NONE 9999
#define OUT_OF_MEMORY -1
#define QUEUE_SIZE 1000

struct _NODE {
  int dist;
  int prev;
};

struct _QITEM {
  int node;
  int dist;
  int prev;
  struct _QITEM *next;
};

struct _NODE dijkstra_rgnNodes[ NUM_NODES ];

int dijkstra_queueCount;
int dijkstra_queueNext;
struct _QITEM *dijkstra_queueHead;
struct _QITEM dijkstra_queueItems[ QUEUE_SIZE ];

int dijkstra_checksum = 0;

void dijkstra_init( void );
int dijkstra_return( void );
int dijkstra_enqueue( int node, int dist, int prev );
void dijkstra_dequeue( int *node, int *dist, int *prev );
int dijkstra_qcount( void );
int dijkstra_find( int chStart, int chEnd );
void dijkstra_main( void );


void dijkstra_init( void )
{
  int i, k;
  volatile int x = 0;
  _Pragma( "loopbound min 100 max 100" )
  for ( i = 0; i < NUM_NODES; i++ ) {
    _Pragma( "loopbound min 100 max 100" )
    for ( k = 0; k < NUM_NODES; k++ )
      dijkstra_AdjMatrix[ i ][ k ] ^= x;
  }

  dijkstra_queueCount = 0;
  dijkstra_queueNext = 0;
  dijkstra_queueHead = ( struct _QITEM * )0;

  dijkstra_checksum = 0;
}

int dijkstra_return( void )
{
  return ( ( dijkstra_checksum == 25 ) ? 0 : -1 );
}

int dijkstra_enqueue( int node, int dist, int prev )
{
  struct _QITEM *newItem = &dijkstra_queueItems[ dijkstra_queueNext ];
  struct _QITEM *last = dijkstra_queueHead;

  if ( ++dijkstra_queueNext >= QUEUE_SIZE )
    return OUT_OF_MEMORY;
  newItem->node = node;
  newItem->dist = dist;
  newItem->prev = prev;
  newItem->next = 0;

  if ( !last )
    dijkstra_queueHead = newItem;
  else {
    /* Items are taken from dijkstra_queueItems in order and appended at the
       tail, so the current tail is the previously allocated item. */
    newItem[ -1 ].next = newItem;
  }
  dijkstra_queueCount++;
  return 0;
}

void dijkstra_dequeue( int *node, int *dist, int *prev )
{
  if ( dijkstra_queueHead ) {
    *node = dijkstra_queueHead->node;
    *dist = dijkstra_queueHead->dist;
    *prev = dijkstra_queueHead->prev;
    dijkstra_queueHead = dijkstra_queueHead->next;
    dijkstra_queueCount--;
  }
}

int dijkstra_qcount( void )
{
  return ( dijkstra_queueCount );
}

int dijkstra_find( int chStart, int chEnd )
{
  int ch;
  int prev, node = 0;
  int cost, dist = 0;
  int i;

  _Pragma( "loopbound min 100 max 100" )
  for ( ch = 0; ch < NUM_NODES; ch++ ) {
    dijkstra_rgnNodes[ ch ].dist = NONE;
    dijkstra_rgnNodes[ ch ].prev = NONE;
  }

  if ( chStart == chEnd ) {
  } else {
    dijkstra_rgnNodes[ chStart ].dist = 0;
    dijkstra_rgnNodes[ chStart ].prev = NONE;

    if ( dijkstra_enqueue ( chStart, 0, NONE ) == OUT_OF_MEMORY )
      return OUT_OF_MEMORY;

    _Pragma( "loopbound min 100 max 1000" )
    while ( dijkstra_qcount() > 0 ) {
      dijkstra_dequeue ( &node, &dist, &prev );
      _Pragma( "loopbound min 100 max 100" )
      for ( i = 0; i < NUM_NODES; i++ ) {
        if ( ( cost = dijkstra_AdjMatrix[ node ][ i ] ) != NONE ) {
          if ( ( NONE == dijkstra_rgnNodes[ i ].dist ) ||
               ( dijkstra_rgnNodes[ i ].dist > ( cost + dist ) ) ) {
            dijkstra_rgnNodes[ i ].dist = dist + cost;
            dijkstra_rgnNodes[ i ].prev = node;
            if ( dijkstra_enqueue ( i, dist + cost, node ) == OUT_OF_MEMORY )
              return OUT_OF_MEMORY;
          }
        }
      }
    }
  }
  return 0;
}

void _Pragma( "entrypoint" ) dijkstra_main( void )
{
  int i, j;

  _Pragma( "loopbound min 20 max 20" )
  for ( i = 0, j = NUM_NODES / 2; i < 20; i++, j++ ) {
    j = j % NUM_NODES;
    if ( dijkstra_find( i, j ) == OUT_OF_MEMORY ) {
      dijkstra_checksum += OUT_OF_MEMORY;
      return;
    } else
      dijkstra_checksum += dijkstra_rgnNodes[ j ].dist;
    dijkstra_queueNext = 0;
  }
}

