/* Saturation as Zbb min/max instead of compare-and-branch. */
static inline long gsm_dec_clamp( long x )
{
  x = x < MIN_WORD ? MIN_WORD : x;
  return x > MAX_WORD ? MAX_WORD : x;
}

/* 0xFFFF & ((a*b + 16384) >> 15) stored to a word, with the
   MIN_WORD*MIN_WORD -> MAX_WORD special case: that product (2^30) is the
   only one whose rounded value exceeds MAX_WORD, so one min() covers it. */
static inline long gsm_dec_mult_r( long a, long b )
{
  long t = ( a * b + 16384 ) >> 15;
  return t > MAX_WORD ? MAX_WORD : t;
}

word gsm_dec_sub( word a, word b )
{
  longword diff = ( longword )a - ( longword )b;
  return saturate( diff );
}

word gsm_dec_asl( word a, int n )
{
  if ( n >= 16 )
    return 0;
  if ( n <= -16 )
    return -( a < 0 );
  if ( n < 0 )
    return gsm_dec_asr( a, -n );
  return a << n;
}

void gsm_dec_Decoding_of_the_coded_Log_Area_Ratios(
  word *LARc,
  word *LARpp )
{
  word temp1  ;
  long ltmp;

#undef STEP
#define STEP(B, MIC, INVA)                                                     \
  temp1 = GSM_ADD(*LARc++, MIC) << 10;                                         \
  temp1 = GSM_SUB(temp1, B << 1);                                              \
  temp1 = GSM_MULT_R(INVA, temp1);                                             \
  *LARpp++ = GSM_ADD(temp1, temp1);

  STEP( 0, -32, 13107 );
  STEP( 0, -32, 13107 );
  STEP( 2048, -16, 13107 );
  STEP( 2560, -16, 13107 );

  STEP( 94, -8, 19223 );
  STEP( 1792, -8, 17476 );
  STEP( 341, -4, 31454 );
  STEP( 1144, -4, 29708 );

}

void gsm_dec_Coefficients_0_12( word *LARpp_j_1, word *LARpp_j, word *LARp )
{
  int i;
  longword ltmp;

  _Pragma( "loopbound min 8 max 8" )
  for ( i = 1; i <= 8; i++, LARp++, LARpp_j_1++, LARpp_j++ ) {
    *LARp = GSM_ADD( SASR( *LARpp_j_1, 2 ), SASR( *LARpp_j, 2 ) );
    *LARp = GSM_ADD( *LARp, SASR( *LARpp_j_1, 1 ) );
  }
}

void gsm_dec_LARp_to_rp( word *LARp )
{
  int i;
  word temp;
  longword ltmp;

  _Pragma( "loopbound min 8 max 8" )
  for ( i = 1; i <= 8; i++, LARp++ ) {

    if ( *LARp < 0 ) {
      temp = *LARp == MIN_WORD ? MAX_WORD : -( *LARp );
      *LARp = -( ( temp < 11059 ) ? temp << 1
                 : ( ( temp < 20070 ) ? temp + 11059
                     : GSM_ADD( temp >> 2, 26112 ) ) );
    } else {
      temp = *LARp;
      *LARp = ( temp < 11059 )
              ? temp << 1
              : ( ( temp < 20070 ) ? temp + 11059 : GSM_ADD( temp >> 2, 26112 ) );
    }
  }
}

void gsm_dec_Decoder( struct gsm_state *S,
                      word *LARcr,
                      word *Ncr,
                      word *bcr,
                      word *Mcr,
                      word *xmaxcr,
                      word *xMcr,
                      word *s )
{
  int j, k;
  word erp[ 40 ], wt[ 160 ];
  word *drp = S->dp0 + 120;

  _Pragma( "loopbound min 4 max 4" )
  for ( j = 0; j <= 3; j++, xmaxcr++, bcr++, Ncr++, Mcr++, xMcr += 13 ) {

    gsm_dec_RPE_Decoding( *xmaxcr, *Mcr, xMcr, erp );
    gsm_dec_Long_Term_Synthesis_Filtering( S, *Ncr, *bcr, erp, drp );

    _Pragma( "loopbound min 40 max 40" )
    for ( k = 0; k <= 39; k++ )
      wt[ j * 40 + k ] = drp[ k ];
  }

  gsm_dec_Short_Term_Synthesis_Filter( S, LARcr, wt, s );
  gsm_dec_Postprocessing( S, s );
}

void gsm_dec_Long_Term_Synthesis_Filtering(
  struct gsm_state *S,
  word Ncr, word bcr, word *erp,
  word *drp
)
{
  longword ltmp;
  int k;
  word brp, drpp, Nr;

  Nr = Ncr < 40 || Ncr > 120 ? S->nrp : Ncr;
  S->nrp = Nr;

  brp = gsm_dec_QLB[ bcr ];

  _Pragma( "loopbound min 40 max 40" )
  for ( k = 0; k <= 39; k++ ) {
    drpp = GSM_MULT_R( brp, drp[ k - Nr ] );
    drp[ k ] = gsm_dec_clamp( ( long )erp[ k ] + drpp );
  }

  _Pragma( "loopbound min 120 max 120" )
  for ( k = 0; k <= 119; k++ )
    drp[ -120 + k ] = drp[ -80 + k ];
}

void gsm_dec_RPE_Decoding( word xmaxcr, word Mcr,
                           word *xMcr,
                           word *erp )
{
  word exp, mant;
  word xMp[ 13 ];

  gsm_dec_APCM_quantization_xmaxc_to_exp_mant( xmaxcr, &exp, &mant );
  gsm_dec_APCM_inverse_quantization( xMcr, mant, exp, xMp );
  gsm_dec_RPE_grid_positioning( Mcr, xMp, erp );
}

void gsm_dec_RPE_grid_positioning(
  word Mc,
  word *xMp,
  word *ep     )
{
  int i = 13;

  switch ( Mc ) {
    case 3:
      *ep++ = 0;
    case 2:
      *ep++ = 0;
    case 1:
      *ep++ = 0;
    case 0:
      *ep++ = *xMp++;
      i--;
  }

  _Pragma( "loopbound min 12 max 12" )
  do {
    *ep++ = 0;
    *ep++ = 0;
    *ep++ = *xMp++;
  } while ( --i );

  _Pragma( "loopbound min 0 max 3" )
  while ( ++Mc < 4 )
    *ep++ = 0;

}

void gsm_dec_APCM_inverse_quantization( word *xMc,
                                        word mant,
                                        word exp,
                                        word *xMp )
{
  int i;
  word temp, temp1, temp2, temp3;
  longword ltmp;

  temp1 = gsm_dec_FAC[ mant ];
  temp2 = gsm_dec_sub( 6, exp );
  temp3 = gsm_dec_asl( 1, gsm_dec_sub( temp2, 1 ) );

  _Pragma( "loopbound min 13 max 13" )
  for ( i = 13; i--; ) {

    temp = ( *xMc++ << 1 ) - 7;

    temp <<= 12;
    temp = GSM_MULT_R( temp1, temp );
    temp = GSM_ADD( temp, temp3 );
    *xMp++ = gsm_dec_asr( temp, temp2 );
  }
}

word gsm_dec_asr( word a, int n )
{
  if ( n >= 16 )
    return -( a < 0 );
  if ( n <= -16 )
    return 0;
  if ( n < 0 )
    return a << -n;

  return a >> n;
}

void gsm_dec_APCM_quantization_xmaxc_to_exp_mant( word xmaxc,
    word *exp_out,
    word *mant_out )
{
  word exp, mant;

  exp = 0;
  if ( xmaxc > 15 )
    exp = SASR( xmaxc, 3 ) - 1;
  mant = xmaxc - ( exp << 3 );

  if ( mant == 0 ) {
    exp = -4;
    mant = 7;
  } else {
    _Pragma( "loopbound min 0 max 3" )
    while ( mant <= 7 ) {
      mant = mant << 1 | 1;
      exp--;
    }
    mant -= 8;
  }

  *exp_out = exp;
  *mant_out = mant;
}

void gsm_dec_Postprocessing( struct gsm_state *S, word *s )
{
  int k;
  word msr = S->msr;
  longword ltmp;
  word tmp;

  _Pragma( "loopbound min 159 max 159" )
  for ( k = 160; --k; ++s ) {
    tmp = GSM_MULT_R( msr, 28180 );
    msr = gsm_dec_clamp( ( long )*s + tmp );
    *s = gsm_dec_clamp( ( long )msr + msr ) & 0xFFF8;
  }
  S->msr = msr;
}

void gsm_dec_Coefficients_13_26( word *LARpp_j_1, word *LARpp_j, word *LARp )
{
  int i;
  longword ltmp;
  _Pragma( "loopbound min 8 max 8" )
  for ( i = 1; i <= 8; i++, LARpp_j_1++, LARpp_j++, LARp++ )
    *LARp = GSM_ADD( SASR( *LARpp_j_1, 1 ), SASR( *LARpp_j, 1 ) );
}

void gsm_dec_Coefficients_40_159( word *LARpp_j, word *LARp )
{
  int i;

  _Pragma( "loopbound min 8 max 8" )
  for ( i = 1; i <= 8; i++, LARp++, LARpp_j++ )
    *LARp = *LARpp_j;
}

#define GSM_DEC_TAP( I, VIN, VOUT )                                    \
  sri = gsm_dec_clamp( sri - gsm_dec_mult_r( r##I, VIN ) );            \
  VOUT = gsm_dec_clamp( VIN + gsm_dec_mult_r( r##I, sri ) );

void gsm_dec_Short_term_synthesis_filtering( struct gsm_state *S,
    word *rrp,
    int k,
    word *wt,
    word *sr )
{
  /* The 8-tap lattice fully unrolled with v[] and rrp[] in registers;
     branch-free saturation. */
  word *v = S->v;
  long r0 = rrp[ 0 ], r1 = rrp[ 1 ], r2 = rrp[ 2 ], r3 = rrp[ 3 ];
  long r4 = rrp[ 4 ], r5 = rrp[ 5 ], r6 = rrp[ 6 ], r7 = rrp[ 7 ];
  long v0 = v[ 0 ], v1 = v[ 1 ], v2 = v[ 2 ], v3 = v[ 3 ];
  long v4 = v[ 4 ], v5 = v[ 5 ], v6 = v[ 6 ], v7 = v[ 7 ], v8 = v[ 8 ];
  long sri;

  _Pragma( "loopbound min 12 max 119" )
  while ( --k ) {
    sri = *wt++;
    GSM_DEC_TAP( 7, v7, v8 )
    GSM_DEC_TAP( 6, v6, v7 )
    GSM_DEC_TAP( 5, v5, v6 )
    GSM_DEC_TAP( 4, v4, v5 )
    GSM_DEC_TAP( 3, v3, v4 )
    GSM_DEC_TAP( 2, v2, v3 )
    GSM_DEC_TAP( 1, v1, v2 )
    GSM_DEC_TAP( 0, v0, v1 )
    *sr++ = v0 = sri;
  }
  v[ 0 ] = v0; v[ 1 ] = v1; v[ 2 ] = v2; v[ 3 ] = v3; v[ 4 ] = v4;
  v[ 5 ] = v5; v[ 6 ] = v6; v[ 7 ] = v7; v[ 8 ] = v8;
}

void gsm_dec_Short_Term_Synthesis_Filter(
  struct gsm_state *S,
  word *LARcr,
  word *wt,
  word *s
)
{
  word *LARpp_j = S->LARpp[ S->j ];
  word *LARpp_j_1 = S->LARpp[ S->j ^= 1 ];

  word LARp[ 8 ];

  gsm_dec_Decoding_of_the_coded_Log_Area_Ratios( LARcr, LARpp_j );

  gsm_dec_Coefficients_0_12( LARpp_j_1, LARpp_j, LARp );
  gsm_dec_LARp_to_rp( LARp );
  gsm_dec_Short_term_synthesis_filtering( S, LARp, 13, wt, s );

  gsm_dec_Coefficients_13_26( LARpp_j_1, LARpp_j, LARp );
  gsm_dec_LARp_to_rp( LARp );
  gsm_dec_Short_term_synthesis_filtering( S, LARp, 14, wt + 13, s + 13 );

  gsm_dec_Coefficients_27_39( LARpp_j_1, LARpp_j, LARp );
  gsm_dec_LARp_to_rp( LARp );
  gsm_dec_Short_term_synthesis_filtering( S, LARp, 13, wt + 27, s + 27 );

  gsm_dec_Coefficients_40_159( LARpp_j, LARp );
  gsm_dec_LARp_to_rp( LARp );
  gsm_dec_Short_term_synthesis_filtering( S, LARp, 120, wt + 40, s + 40 );
}

void gsm_dec_Coefficients_27_39( word *LARpp_j_1, word *LARpp_j, word *LARp )
{
  int i;
  longword ltmp;

  _Pragma( "loopbound min 8 max 8" )
  for ( i = 1; i <= 8; i++, LARpp_j_1++, LARpp_j++, LARp++ ) {
    *LARp = GSM_ADD( SASR( *LARpp_j_1, 2 ), SASR( *LARpp_j, 2 ) );
    *LARp = GSM_ADD( *LARp, SASR( *LARpp_j, 1 ) );
  }
}

gsm gsm_dec_create( void )
{
  unsigned int i;
  gsm r;
  volatile char x = 0;

  r = &gsm_dec_state;

  _Pragma( "loopbound min 648 max 648" )
  for ( i = 0; i < sizeof( *r ); i++ )
    ( ( char * )r )[ i ] = 0 + x;

  r->nrp = 40;

  return r;
}

void gsm_dec_init( void )
{
  gsm_dec_state_ptr = gsm_dec_create();
}

int gsm_dec_return( void )
{
  return gsm_dec_result;
}

int gsm_dec_decode( gsm s, gsm_byte *c, gsm_signal *target )
{
  word LARc[ 8 ], Nc[ 4 ], Mc[ 4 ], bc[ 4 ], xmaxc[ 4 ], xmc[ 13 * 4 ];

  if ( ( ( *c >> 4 ) & 0x0F ) != GSM_MAGIC )
    return -1;

  LARc[ 0 ] = ( *c++ & 0xF ) << 2;
  LARc[ 0 ] |= ( *c >> 6 ) & 0x3;
  LARc[ 1 ] = *c++ & 0x3F;
  LARc[ 2 ] = ( *c >> 3 ) & 0x1F;
  LARc[ 3 ] = ( *c++ & 0x7 ) << 2;
  LARc[ 3 ] |= ( *c >> 6 ) & 0x3;
  LARc[ 4 ] = ( *c >> 2 ) & 0xF;
  LARc[ 5 ] = ( *c++ & 0x3 ) << 2;
  LARc[ 5 ] |= ( *c >> 6 ) & 0x3;
  LARc[ 6 ] = ( *c >> 3 ) & 0x7;
  LARc[ 7 ] = *c++ & 0x7;
  Nc[ 0 ] = ( *c >> 1 ) & 0x7F;
  bc[ 0 ] = ( *c++ & 0x1 ) << 1;
  bc[ 0 ] |= ( *c >> 7 ) & 0x1;
  Mc[ 0 ] = ( *c >> 5 ) & 0x3;
  xmaxc[ 0 ] = ( *c++ & 0x1F ) << 1;
  xmaxc[ 0 ] |= ( *c >> 7 ) & 0x1;
  xmc[ 0 ] = ( *c >> 4 ) & 0x7;
  xmc[ 1 ] = ( *c >> 1 ) & 0x7;
  xmc[ 2 ] = ( *c++ & 0x1 ) << 2;
  xmc[ 2 ] |= ( *c >> 6 ) & 0x3;
  xmc[ 3 ] = ( *c >> 3 ) & 0x7;
  xmc[ 4 ] = *c++ & 0x7;
  xmc[ 5 ] = ( *c >> 5 ) & 0x7;
  xmc[ 6 ] = ( *c >> 2 ) & 0x7;
  xmc[ 7 ] = ( *c++ & 0x3 ) << 1;
  xmc[ 7 ] |= ( *c >> 7 ) & 0x1;
  xmc[ 8 ] = ( *c >> 4 ) & 0x7;
  xmc[ 9 ] = ( *c >> 1 ) & 0x7;
  xmc[ 10 ] = ( *c++ & 0x1 ) << 2;
  xmc[ 10 ] |= ( *c >> 6 ) & 0x3;
  xmc[ 11 ] = ( *c >> 3 ) & 0x7;
  xmc[ 12 ] = *c++ & 0x7;
  Nc[ 1 ] = ( *c >> 1 ) & 0x7F;
  bc[ 1 ] = ( *c++ & 0x1 ) << 1;
  bc[ 1 ] |= ( *c >> 7 ) & 0x1;
  Mc[ 1 ] = ( *c >> 5 ) & 0x3;
  xmaxc[ 1 ] = ( *c++ & 0x1F ) << 1;
  xmaxc[ 1 ] |= ( *c >> 7 ) & 0x1;
  xmc[ 13 ] = ( *c >> 4 ) & 0x7;
  xmc[ 14 ] = ( *c >> 1 ) & 0x7;
  xmc[ 15 ] = ( *c++ & 0x1 ) << 2;
  xmc[ 15 ] |= ( *c >> 6 ) & 0x3;
  xmc[ 16 ] = ( *c >> 3 ) & 0x7;
  xmc[ 17 ] = *c++ & 0x7;
  xmc[ 18 ] = ( *c >> 5 ) & 0x7;
  xmc[ 19 ] = ( *c >> 2 ) & 0x7;
  xmc[ 20 ] = ( *c++ & 0x3 ) << 1;
  xmc[ 20 ] |= ( *c >> 7 ) & 0x1;
