/* Exact C signed division by 2^sh (rounds toward zero). */
static inline int h264_dec_sdiv( int x, int sh )
{
  return ( x + ( ( x >> 31 ) & ( ( 1 << sh ) - 1 ) ) ) >> sh;
}

/* log2(d) if d is a positive power of two, else -1. */
static inline int h264_dec_log2( int d )
{
  return ( d > 0 && ( d & ( d - 1 ) ) == 0 ) ? __builtin_ctz( d ) : -1;
}

/* (0 < min(x, hi)) ? min(x, hi) : 0  ==  max(min(x, hi), 0): Zbb min/max */
static inline int h264_dec_clip( int x, int hi )
{
  x = x > hi ? hi : x;
  return x < 0 ? 0 : x;
}

void h264_dec_decode_one_macroblock( struct h264_dec_img_par *img )
{
  /* All divisors of the chroma MC path are runtime values; when they are
     powers of two (checked once) the per-pixel divisions become exact
     shift sequences and the clips become min/max.  Otherwise the original
     code runs.  Only the path the original takes (pred_dir = -1,
     intra_prediction = 0, curr_mb_field = 0, smb = 0) is specialised. */
  int f1_x, f2_x, f1_y, f2_y, f3, f4;
  int sx, sy, s3, sx4, sy4;
  int uv, b8, b4, ii, jj;
  int max_y_cr = 287;

  if ( img->mb_cr_size_x <= 0 || img->mb_cr_size_y <= 0 ) {
    h264_dec_decode_generic( img );
    return;
  }
  f1_x = 64 / img->mb_cr_size_x;
  f2_x = f1_x - 1;
  f1_y = 64 / img->mb_cr_size_y;
  f2_y = f1_y - 1;
  f3 = f1_x * f1_y;
  f4 = f3 >> 1;
  sx = h264_dec_log2( f1_x );
  sy = h264_dec_log2( f1_y );
  s3 = h264_dec_log2( f3 );
  sx4 = h264_dec_log2( img->mb_cr_size_x / 4 );
  sy4 = h264_dec_log2( img->mb_cr_size_y / 4 );
  if ( ( sx | sy | s3 | sx4 | sy4 ) < 0 ) {
    h264_dec_decode_generic( img );
    return;
  }

  {
    const int wmax = img->width_cr - 1;
    const int j4 = img->pix_c_y, i4 = img->pix_c_x;
    const int nb8 = img->num_blk8x8_uv / 2;
    const unsigned int apply_weights = img->apply_weights;

    _Pragma( "loopbound min 2 max 2" )
    for ( uv = 0; uv < 2; uv++ ) {
      const short ( *ref )[ 45 ] = h264_dec_list_imgUV[ uv ];
      _Pragma( "loopbound min 1 max 1" )
      for ( b8 = 0; b8 < nb8; b8++ ) {
        _Pragma( "loopbound min 4 max 4" )
        for ( b4 = 0; b4 < 4; b4++ ) {
          _Pragma( "loopbound min 4 max 4" )
          for ( jj = 0; jj < 4; jj++ ) {
            int jf = h264_dec_sdiv( j4 + jj, sy4 ) % 64;
            _Pragma( "loopbound min 4 max 4" )
            for ( ii = 0; ii < 4; ii++ ) {
              int ifx = h264_dec_sdiv( i4 + ii, sx4 ) % 64;
              int i1 = ( i4 + ii ) * f1_x + h264_dec_mv_array[ jf ][ ifx ][ 0 ];
              int j1 = ( j4 + jj ) * f1_y + h264_dec_mv_array[ jf ][ ifx ][ 1 ];
              int ii0 = h264_dec_clip( h264_dec_sdiv( i1, sx ), wmax ) % 45;
              int jj0 = h264_dec_clip( h264_dec_sdiv( j1, sy ), max_y_cr ) % 45;
              int ii1 = h264_dec_clip( h264_dec_sdiv( i1 + f2_x, sx ), wmax ) % 45;
              int jj1 = h264_dec_clip( h264_dec_sdiv( j1 + f2_y, sy ), max_y_cr ) % 45;
              int if1 = i1 & f2_x, jf1 = j1 & f2_y;
              int if0 = f1_x - if1, jf0 = f1_y - jf1;
              if ( !apply_weights )
                h264_dec_img_mpr[ ii ][ jj ] = h264_dec_sdiv(
                    if0 * jf0 * ref[ jj0 ][ ii0 ] + if1 * jf0 * ref[ jj0 ][ ii1 ]
                    + if0 * jf1 * ref[ jj1 ][ ii0 ] + if1 * jf1 * ref[ jj1 ][ ii1 ]
                    + f4, s3 );
            }
          }
          _Pragma( "loopbound min 4 max 4" )
          for ( ii = 0; ii < 4; ii++ )
            _Pragma( "loopbound min 4 max 4" )
            for ( jj = 0; jj < 4; jj++ )
              h264_dec_dec_picture_imgUV[ uv ][ ( j4 + jj ) % 64 ][ ( i4 + ii ) % 54 ]
                = h264_dec_img_m7[ ii ][ jj ];
        }
      }
    }
  }
}

void _Pragma( "entrypoint" )  h264_dec_main( void )
{
  h264_dec_decode_one_macroblock( &h264_dec_img );
}

