    huff_enc_put_bits( &bin_val_to_1 );
    _Pragma( "loopbound min 256 max 256" )
    for ( j = 0; j <= 255; j++ )
      if ( codes_table[ j ].bits_nb )
        huff_enc_put_bits( &bin_val_to_1 );
      else huff_enc_put_bits( &bin_val_to_0 );
