  for ( i = 0; i <= 256; i++ )
    if ( ( j = codes_table[ i ].bits_nb ) != 0 ) {
      if ( j < 33 ) {
        huff_enc_put_bits( &bin_val_to_0 );
        bin_val.bits_nb = 5;
      } else {
        huff_enc_put_bits( &bin_val_to_1 );
        bin_val.bits_nb = 8;
      }
      *bin_val.bits = ( unsigned char )( j - 1 );
      huff_enc_put_bits( &bin_val );
      huff_enc_put_bits( &codes_table[ i ] );
    }
