    if ( huff_enc_weighhuff_enc_t_tree_comp( pi, pk ) < 0 ) {
      if ( huff_enc_weighhuff_enc_t_tree_comp( pj, pk ) < 0 )
        return pj;
      return pk;
    }
    return pi;
  }
  if ( huff_enc_weighhuff_enc_t_tree_comp( pj, pk ) < 0 ) {
    if ( huff_enc_weighhuff_enc_t_tree_comp( pi, pk ) < 0 )
      return pi;
    return pk;
  }
  return pj;
}

void huff_enc_qsort( char *a, unsigned long n, unsigned long es )
