/* huff_enc_qsort specialised for arrays of tree pointers (es == 8): the
   same partitioning steps, but pointer swaps and inlined weight compares
   (comp(x, y) < 0  <=>  w(x) > w(y)), so the permutation is identical. */
static void huff_enc_qsort_p( huff_enc_t_tree **a, unsigned long n )
{
  unsigned long j;
  huff_enc_t_tree **pi, **pj, **pn, *t;
