      unsigned long s = n / 6;
      huff_enc_t_tree **q1 = a + s, **q2 = q1 + 2 * s, **q3 = q2 + 2 * s;
      unsigned long w1 = ( *q1 )->weight, w2 = ( *q2 )->weight, w3 = ( *q3 )->weight;
      if ( w1 > w2 )
        pi = w1 > w3 ? ( w2 > w3 ? q2 : q3 ) : q1;
      else
        pi = w2 > w3 ? ( w1 > w3 ? q1 : q3 ) : q2;
    } else
      pi = a + ( n >> 1 );
    t = *a; *a = *pi; *pi = t;
    {
      unsigned long wa = ( *a )->weight;
      pi = a;
      pn = a + n;
      pj = pn;
      while ( 1 ) {
        do {
          pi++;
        } while ( pi < pn && ( *pi )->weight > wa );
        do {
          pj--;
        } while ( pj > a && wa > ( *pj )->weight );
        if ( pj < pi )
          break;
        t = *pi; *pi = *pj; *pj = t;
      }
    }
    t = *a; *a = *pj; *pj = t;
    j = pj - a;
    n = n - j - 1;
    if ( j >= n ) {
      huff_enc_qsort_p( a, j );
