/* code_val->bits (32 bytes, little-endian) shifted left by one bit, in
   four 64-bit words; the new low bit is b. */
static inline void huff_enc_shl1( huff_enc_t_bin_val *cv, unsigned long b )
{
  unsigned long w[ 4 ];
  __builtin_memcpy( w, cv->bits, 32 );
  w[ 3 ] = ( w[ 3 ] << 1 ) | ( w[ 2 ] >> 63 );
  w[ 2 ] = ( w[ 2 ] << 1 ) | ( w[ 1 ] >> 63 );
  w[ 1 ] = ( w[ 1 ] << 1 ) | ( w[ 0 ] >> 63 );
  w[ 0 ] = ( w[ 0 ] << 1 ) | b;
  __builtin_memcpy( cv->bits, w, 32 );
}

huff_enc_t_tree *huff_enc_build_tree_encoding( huff_enc_t_tree heap[ 514 ] )
{
