  for ( i = 0; i <= 256; i++ ) {
    occurrences_table[ i ] = &heap[ heap_top++ ];
    occurrences_table[ i ]->byte = i;
    occurrences_table[ i ]->weight = 0;
    occurrences_table[ i ]->left_ptr = 0;
    occurrences_table[ i ]->right_ptr = 0;
