    unsigned long e_, c_;                            \
    ( r ) = ( ( r ) << 2 ) + TOP2BITS( x );          \
    ( x ) <<= 2;                                     \
    ( a ) <<= 1;                                     \
    e_ = ( ( a ) << 1 ) + 1;                         \
    c_ = ( r ) >= e_;                                \
    ( r ) -= zc_if( c_, e_ );                        \
    ( a ) += c_;                                     \
  } while ( 0 )

