  int loadLevel = lift_loadLevel, loadPending = lift_loadPending;
  int loadSensor = lift_loadSensor, cmd = lift_cmd, timMotor = lift_timMotor;
  int timImp = lift_timImp, directionUp = lift_directionUp;
  int lastImp = lift_lastImp, dbgCnt = lift_dbgCnt, endCnt = lift_endCnt;
  int dly1 = lift_ctrl_dly1, dly2 = lift_ctrl_dly2;
  int out0 = lift_ctrl_io_out[ lift_MOTOR_ON ];
  int out1 = lift_ctrl_io_out[ lift_MOTOR_UP ];
