  unsigned inb = 0, led13 = 0;
  int a0 = 0, a1 = 0, a2 = 0;

  _Pragma( "loopbound min 1001 max 1001" )
  while ( 1 ) {
    lift_simio_in = 0;
    lift_simio_adc1 = 0;
    lift_simio_adc2 = 0;
    lift_simio_adc3 = 0;

    /* lift_ctrl_get_vals: 2-of-3 majority of the delayed inputs */
    {
      unsigned in0 = ( unsigned short )lift_simio_in;
      unsigned in1 = ( unsigned short )dly1;
      unsigned in2 = ( unsigned short )dly2;
      dly2 = dly1;
      dly1 = in0;
      inb = ( ( in0 & in1 ) | ( in0 & in2 ) | ( in1 & in2 ) ) & 0x3ff;
      a0 = lift_simio_adc1;
      a1 = lift_simio_adc2;
      a2 = lift_simio_adc3;
    }

    /* lift_ctrl_loop */
    if ( cmd == lift_CMD_NONE ) {
      if ( loadPending ) {
        if ( IN( lift_SENS_BOTTOM ) )
          cmd = lift_CMD_TOP;
      } else if ( IN( lift_GO_UP ) ) {
        if ( !IN( lift_SENS_TOP ) && level != 14 )
          cmd = lift_CMD_UP;
      } else if ( IN( lift_GO_DOWN ) ) {
        if ( !IN( lift_SENS_BOTTOM ) && level != 1 )
          cmd = lift_CMD_DOWN;
      } else if ( IN( lift_GO_LOAD ) ) {
        if ( loadLevel != 0 && level < loadLevel )
          cmd = lift_CMD_TOP;
        else
          cmd = lift_CMD_BOTTOM;
        loadPending = 1;
        loadSensor = 0;
      } else if ( IN( lift_GO_TOP ) ) {
        if ( !IN( lift_SENS_TOP ) )
          cmd = lift_CMD_TOP;
      } else if ( IN( lift_GO_BOTTOM ) ) {
        if ( !IN( lift_SENS_BOTTOM ) )
          cmd = lift_CMD_BOTTOM;
      }
      if ( cmd != lift_CMD_NONE )
        timMotor = 50;
    } else {
      /* lift_do_impulse */
      int val = IN( lift_SENS_IMPULS );
      if ( val && !lastImp && ( out0 || timImp > 0 ) )
        cnt += directionUp ? 1 : -1;
      if ( IN( lift_SENS_BOTTOM ) ) {
        cnt = 0;
        cntValid = 1;
      }
      lastImp = val;
      if ( timImp > 0 ) {
        --timImp;
        if ( timImp == 0 && cmd != lift_CMD_NONE )
          cmd = lift_CMD_NONE;
      }
      /* lift_do_cmd */
      if ( timMotor > 0 ) {
        int newLevel;
        --timMotor;
        directionUp = ( cmd == lift_CMD_UP || cmd == lift_CMD_TOP );
        out1 = directionUp;
        if ( !cntValid ) {
          cnt = 0;
          endCnt = cmd == lift_CMD_UP ? one_level : -one_level;
        } else {
          endCnt = cnt;
          newLevel = -99;
          if ( cmd == lift_CMD_UP )
            newLevel = level + 1;
          else if ( cmd == lift_CMD_DOWN )
            newLevel = level - 1;
          --newLevel;
          if ( newLevel >= 0 && newLevel < 14 )
            endCnt = lift_levelPos[ newLevel ];
        }
      } else {
        int run = 0;
        if ( cmd == lift_CMD_UP ) {
          run = cnt < endCnt - 1 && !IN( lift_SENS_TOP );
        } else if ( cmd == lift_CMD_DOWN ) {
          run = cnt > endCnt + 1 && !IN( lift_SENS_BOTTOM );
        } else if ( cmd == lift_CMD_TOP ) {
          if ( loadPending && IN( lift_SENS_LOAD ) ) {
            loadLevel = level;
            loadPending = 0;
          } else if ( !IN( lift_SENS_TOP ) )
            run = 1;
          else
            loadPending = 0;
        } else if ( cmd == lift_CMD_BOTTOM ) {
          int done = 0;
          if ( loadPending ) {
            if ( loadSensor && !IN( lift_SENS_LOAD ) ) {
              loadSensor = 0;
              loadPending = 0;
              loadLevel = level;
              done = 1;
            } else
              loadSensor = IN( lift_SENS_LOAD );
          }
          if ( !done && !IN( lift_SENS_BOTTOM ) )
            run = 1;
        }
        if ( out0 && !run ) {
          cmd = 99;
          timImp = 50;
        }
        out0 = run;
      }
    }

    /* lift_check_level */
    if ( cntValid ) {
      for ( level = 1; level < 14; ++level )
        if ( cnt < lift_levelPos[ level ] - middle )
          break;
    } else
      level = 0;
    led13 = ( dbgCnt & 0x80 ) != 0;
    ++dbgCnt;

    /* lift_ctrl_set_vals: LED k is (k == level - 1), LED 13 is the debug bit */
    {
      unsigned lm = ( unsigned )( level - 1 ) < 13 ? 1u << ( level - 1 ) : 0;
      int val = ( out0 != 0 ) | ( ( out1 != 0 ) << 1 ) | outhi;
      lift_simio_out = val;
      val = ( val << 14 ) | lm | ( led13 << 13 );
      lift_simio_led = val;
