    lift_ctrl_io_in[ k ] = IN( k );
  lift_ctrl_io_analog[ 0 ] = a0;
  lift_ctrl_io_analog[ 1 ] = a1;
  lift_ctrl_io_analog[ 2 ] = a2;
  for ( k = 0; k < 13; k++ )
    lift_ctrl_io_led[ k ] = ( k == level - 1 );
  lift_ctrl_io_led[ 13 ] = led13;
  lift_ctrl_io_out[ lift_MOTOR_ON ] = out0;
  lift_ctrl_io_out[ lift_MOTOR_UP ] = out1;
  lift_ctrl_dly1 = dly1;
  lift_ctrl_dly2 = dly2;
  lift_cntValid = cntValid;
  lift_cnt = cnt;
  lift_level = level;
  lift_loadLevel = loadLevel;
  lift_loadPending = loadPending;
  lift_loadSensor = loadSensor;
  lift_cmd = cmd;
  lift_timMotor = timMotor;
  lift_timImp = timImp;
  lift_directionUp = directionUp;
  lift_lastImp = lastImp;
  lift_dbgCnt = dbgCnt;
  lift_endCnt = endCnt;
  lift_checksum = checksum;
}

