    pivot = r == 0 ? m[ 0 ][ k ] : r == 1 ? m[ 1 ][ k ] : m[ 2 ][ k ];
    api = __builtin_fabs( pivot );
    if ( api <= eps ) {
      for ( i = 0; i < 3; i++ )
        for ( j = 0; j < 3; j++ )
          minver_a[ i ][ j ] = m[ i ][ j ];
      minver_det = w1;
      return ( 1 );
    }
    w1 *= pivot;
    if ( r != k ) {
      w1 = -w;
      iw = work[ k ];
      work[ k ] = work[ r ];
      work[ r ] = iw;
      #pragma GCC unroll 3
      for ( i = 0; i < 3; i++ ) {
        long s = r == i;
        if ( i == k ) continue;
        #pragma GCC unroll 3
        for ( j = 0; j < 3; j++ ) {
          double tk = m[ k ][ j ], ti = m[ i ][ j ];
          m[ k ][ j ] = zc_seld( s, ti, tk );
          m[ i ][ j ] = zc_seld( s, tk, ti );
        }
      }
    }
    #pragma GCC unroll 3
    for ( i = 0; i < 3; i++ )
      m[ k ][ i ] /= pivot;
    #pragma GCC unroll 3
    for ( i = 0; i < 3; i++ ) {
      if ( i != k ) {
        w = m[ i ][ k ];
        if ( w != 0.0 ) {
          #pragma GCC unroll 3
          for ( j = 0; j < 3; j++ ) {
            if ( j != k ) m[ i ][ j ] -= w * m[ k ][ j ];
          }
          m[ i ][ k ] = -w / pivot;
        }
      }
    }
    m[ k ][ k ] = 1.0 / pivot;
  }
  for ( i = 0; i < 3; ) {
    while ( 1 ) {
      k = work[ i ];
      if ( k == i ) break;
      iw = work[ k ];
      work[ k ] = work[ i ];
      work[ i ] = iw;
      for ( j = 0; j < 3; j++ ) {
        w = m[ k ][ i ];
        m[ k ][ i ] = m[ k ][ k ];
        m[ k ][ k ] = w;
      }
    }
    i++;
  }
  for ( i = 0; i < 3; i++ )
    for ( j = 0; j < 3; j++ )
      minver_a[ i ][ j ] = m[ i ][ j ];
  minver_det = w1;
  return ( 0 );
}

int minver_minver( int side, double eps )
{

  int work[ 500 ], i, j, k, iw;
  int r = 0;
  double w = 0, wmax, pivot, api, w1;

  if ( side < 2 || side > 500 || eps <= 0.0 )
    return ( 999 );
  if ( side == 3 )
    return minver_minver3( eps );
  w1 = 1.0;
  _Pragma( "loopbound min 3 max 3" )
  for ( i = 0; i < side; i++ )
    work[ i ] = i;
  _Pragma( "loopbound min 3 max 3" )
  for ( k = 0; k < side; k++ ) {
    wmax = 0.0;
    _Pragma( "loopbound min 1 max 3" )
    for ( i = k; i < side; i++ ) {
      w = minver_fabs( minver_a[ i ][ k ] );
      if ( w > wmax ) {
        wmax = w;
        r = i;
      }
    }
    pivot = minver_a[ r ][ k ];
    api = minver_fabs( pivot );
    if ( api <= eps ) {
      minver_det = w1;
      return ( 1 );
    }
    w1 *= pivot;
    if ( r != k ) {
      w1 = -w;
      iw = work[ k ];
      work[ k ] = work[ r ];
      work[ r ] = iw;
      _Pragma( "loopbound min 3 max 3" )
      for ( j = 0; j < side; j++ ) {
        w = minver_a[ k ][ j ];
        minver_a[ k ][ j ] = minver_a[ r ][ j ];
        minver_a[ r ][ j ] = w;
      }
    }
    _Pragma( "loopbound min 3 max 3" )
    for ( i = 0; i < side; i++ )
      minver_a[ k ][ i ] /= pivot;
    _Pragma( "loopbound min 3 max 3" )
    for ( i = 0; i < side; i++ ) {
      if ( i != k ) {
        w = minver_a[ i ][ k ];
        if ( w != 0.0 ) {
          _Pragma( "loopbound min 3 max 3" )
          for ( j = 0; j < side; j++ ) {
            if ( j != k ) minver_a[ i ][ j ] -= w * minver_a[ k ][ j ];
          }
          minver_a[ i ][ k ] = -w / pivot;

        }
      }
    }
    minver_a[ k ][ k ] = 1.0 / pivot;
  }
  _Pragma( "loopbound min 3 max 3" )
  for ( i = 0; i < side; ) {
    _Pragma( "loopbound min 1 max 3" )
    while ( 1 ) {
      k = work[ i ];
      if ( k == i ) break;
      iw = work[ k ];
      work[ k ] = work[ i ];
      work[ i ] = iw;
      _Pragma( "loopbound min 3 max 3" )
      for ( j = 0; j < side; j++ ) {
        w = minver_a [k ][ i ];
        minver_a[ k ][ i ] = minver_a[ k ][ k ];
        minver_a[ k ][ k ] = w;
      }
    }
    i++;
  }
  minver_det = w1;
  return ( 0 );

}

void minver_init()
{
  int i, j;
  volatile int x = 0;

  _Pragma( "loopbound min 3 max 3" )
  for ( i = 0; i < 3; i++ ) {
    _Pragma( "loopbound min 3 max 3" )
    for ( j = 0; j < 3; j++ )
      minver_a[ i ][ j ] += x;
  }
}

int minver_return()
{
  int i, j;
  double check_sum = 0;

  _Pragma( "loopbound min 3 max 3" )
  for ( i = 0; i < 3; i++ ) {
    _Pragma( "loopbound min 3 max 3" )
    for ( j = 0; j < 3; j++ )
      check_sum += minver_a_i[ i ][ j ];
  }

  return ( int )( check_sum * 100 ) != 48;
}

void _Pragma( "entrypoint" ) minver_main()
{
  int i, j;
  double eps;
  eps = 1.0e-6;
  _Pragma( "loopbound min 3 max 3" )
  for ( i = 0; i < 3; i++ ) {
    _Pragma( "loopbound min 3 max 3" )
    for ( j = 0; j < 3; j++ )
      minver_aa[ i ][ j ] = minver_a[ i ][ j ];
  }

  minver_minver( 3, eps );
  _Pragma( "loopbound min 3 max 3" )
  for ( i = 0; i < 3; i++ ) {
    _Pragma( "loopbound min 3 max 3" )
    for ( j = 0; j < 3; j++ )
      minver_a_i[ i ][ j ] = minver_a[ i ][ j ];
  }

  minver_mmul( 3, 3, 3, 3 );
}

