    ndes_icd.r = ndes_icd.l = 0L;

    _Pragma( "loopbound min 28 max 28" )
    for ( j = 28, k = 56; j >= 1; j--, k-- ) {
      ndes_icd.r = ( ndes_icd.r << 1 ) | ndes_getbit( key, ndes_ipc1[ j ], 32 );
      ndes_icd.l = ndes_icd.l << 1;
