/* Zicond select: c ? a : b, branch-free. */
static inline long zc_sel( long c, long a, long b )
{
#ifdef __riscv_zicond
  long t, f;
  __asm__( "czero.eqz %0, %1, %2" : "=r"( t ) : "r"( a ), "r"( c ) );
  __asm__( "czero.nez %0, %1, %2" : "=r"( f ) : "r"( b ), "r"( c ) );
  return t | f;
#else
  return c ? a : b;
#endif
}

static inline unsigned long qs_ld8( const char *p )
{
  unsigned long v;
  __builtin_memcpy( &v, p, 8 );
  return v;
}

static inline unsigned long qs_ld4( const char *p )
{
  unsigned int v;
  __builtin_memcpy( &v, p, 4 );
  return v;
}

/* 0xff in every byte of v that is non-zero (Zbb orc.b). */
static inline unsigned long qs_orc( unsigned long v )
{
#ifdef __riscv_zbb
  unsigned long r;
  __asm__( "orc.b %0, %1" : "=r"( r ) : "r"( v ) );
  return r;
#else
  unsigned long r = 0;
  for ( int i = 0; i < 64; i += 8 )
    if ( ( v >> i ) & 0xff ) r |= 0xffUL << i;
  return r;
#endif
}

/* strcmp sign of two char[20] rows (each holds a NUL within its 20 bytes):
   8 bytes at a time, stop mask = NUL in a | byte differs; returns the
   unsigned byte difference at the first stop position like strcmp. */
static inline long qs_strdiff( const char *a, const char *b )
{
  unsigned long x, y, m;
  x = qs_ld8( a ); y = qs_ld8( b );
  m = ~qs_orc( x ) | qs_orc( x ^ y );
  if ( !m ) {
    x = qs_ld8( a + 8 ); y = qs_ld8( b + 8 );
    m = ~qs_orc( x ) | qs_orc( x ^ y );
    if ( !m ) {
      x = qs_ld4( a + 16 ); y = qs_ld4( b + 16 );
      m = ~qs_orc( x ) | qs_orc( x ^ y );
    }
  }
  int sh = __builtin_ctzl( m ) & ~7;
  return ( long )( ( x >> sh ) & 0xff ) - ( long )( ( y >> sh ) & 0xff );
}

/* quicksort_compare_strings( pi, a ) < 0  <=>  strcmp( pi, a ) > 0 */
#define QS_STR_LT( p, q ) ( qs_strdiff( ( p ), ( q ) ) > 0 )
#define QS_STR_GT( p, q ) ( qs_strdiff( ( p ), ( q ) ) < 0 )

static inline double qs_dist( const char *p )
{
  return ( ( const struct quicksort_3DVertexStruct * )p )->distance;
}

static inline void qs_swap20( char *p, char *q )
{
  unsigned long a0, a1, b0, b1;
  unsigned int a2, b2;
  __builtin_memcpy( &a0, p, 8 ); __builtin_memcpy( &a1, p + 8, 8 ); __builtin_memcpy( &a2, p + 16, 4 );
  __builtin_memcpy( &b0, q, 8 ); __builtin_memcpy( &b1, q + 8, 8 ); __builtin_memcpy( &b2, q + 16, 4 );
  __builtin_memcpy( p, &b0, 8 ); __builtin_memcpy( p + 8, &b1, 8 ); __builtin_memcpy( p + 16, &b2, 4 );
  __builtin_memcpy( q, &a0, 8 ); __builtin_memcpy( q + 8, &a1, 8 ); __builtin_memcpy( q + 16, &a2, 4 );
}

static inline void qs_swap24( char *p, char *q )
{
  struct quicksort_3DVertexStruct t = *( struct quicksort_3DVertexStruct * )p;
  *( struct quicksort_3DVertexStruct * )p = *( struct quicksort_3DVertexStruct * )q;
  *( struct quicksort_3DVertexStruct * )q = t;
}

/* Median-of-three of the library pivot functions, as czero selects.
   lt(x, y) stands for compare(x, y) < 0. */
#define QS_MED3( pi, pj, pk, lt_ij, lt_ik, lt_jk )                                   \
  ( char * )zc_sel( lt_ij,                                                         \
                    zc_sel( lt_ik, zc_sel( lt_jk, ( long )( pj ), ( long )( pk ) ), ( long )( pi ) ), \
                    zc_sel( lt_jk, zc_sel( lt_ik, ( long )( pi ), ( long )( pk ) ), ( long )( pj ) ) )

static inline char *qs_pivot_strings( char *a, unsigned long n )
{
  long j = n / 6 * 20;
  char *pi = a + j, *pj = pi + 2 * j, *pk = pj + 2 * j;
  long ij = QS_STR_LT( pi, pj ), ik = QS_STR_LT( pi, pk ), jk = QS_STR_LT( pj, pk );
  return QS_MED3( pi, pj, pk, ij, ik, jk );
}

static inline char *qs_pivot_vectors( char *a, unsigned long n )
{
  long j = n / 6 * 24;
  char *pi = a + j, *pj = pi + 2 * j, *pk = pj + 2 * j;
  double di = qs_dist( pi ), dj = qs_dist( pj ), dk = qs_dist( pk );
  /* compare_vectors( x, y ) < 0  <=>  !( dx > dy ) && dx != dy */
  long ij = !( di > dj ) && di != dj, ik = !( di > dk ) && di != dk, jk = !( dj > dk ) && dj != dk;
  return QS_MED3( pi, pj, pk, ij, ik, jk );
}

void quicksort_init( void );
int quicksort_return( void );
void quicksort_str( char *, unsigned long, unsigned long );
void quicksort_vec( char *, unsigned long, unsigned long );
void quicksort_main( void );


extern const char *quicksort_input_string[  681  ];
char quicksort_strings[  681  ][  20  ];

extern unsigned int quicksort_input_vector[  1000 * 3  ];
struct quicksort_3DVertexStruct quicksort_vectors[  1000  ];

volatile int quicksort_const_prop_border_i = 0;
volatile char quicksort_const_prop_border_c = 0;

void quicksort_init( void )
{
  unsigned int i, j;
  unsigned int x, y, z;
  unsigned int read_counter = 0;

  _Pragma( "loopbound min 3000 max 3000" )
  for ( i = 0; i < 3000; i++ )
    quicksort_input_vector[  i  ] += quicksort_const_prop_border_i;

  _Pragma( "loopbound min 681 max 681" )
  for ( i = 0; i < 681; i++ ) {
    _Pragma( "loopbound min 1 max 20" )
    for ( j = 0; j < 20 - 1; j++ ) {
      quicksort_strings[  i  ][  j  ] = quicksort_input_string[  i  ][  j  ];
      quicksort_strings[  i  ][  j  ] += quicksort_const_prop_border_c;

      if ( quicksort_input_string[  i  ][  j  ] == '\0' )
        break;
    }

    quicksort_strings[  i  ][  20 - 1  ] = '\0';
  }

  _Pragma( "loopbound min 1000 max 1000" )
  for ( i = 0; i < 1000; i++ ) {
    x = quicksort_vectors[  i  ].x = quicksort_input_vector[  read_counter++  ];
    y = quicksort_vectors[  i  ].y = quicksort_input_vector[  read_counter++  ];
    z = quicksort_vectors[  i  ].z = quicksort_input_vector[  read_counter++  ];

    /* quicksort_pow( v, 2 ) returns v * v (its y == 2 case) and the libm
       sqrtf is correctly rounded, which is exactly what fsqrt.s computes. */
    float fx = x, fy = y, fz = z;
    float px = fx * fx, py = fy * fy, pz = fz * fz;
    /* keep the products rounded separately, as the pow calls do (no fma) */
#ifdef __riscv
    __asm__( "" : "+f"( px ), "+f"( py ), "+f"( pz ) );
#else
    __asm__( "" : "+w"( px ), "+w"( py ), "+w"( pz ) );
#endif
    quicksort_vectors[  i  ].distance = __builtin_sqrtf( px + py + pz );
  }
}

int quicksort_return( void )
{
  int checksum = 0;

  checksum +=
    quicksort_strings[  42  ][  1  ] +
    quicksort_vectors[  42  ].x + quicksort_vectors[  42  ].y +
    quicksort_vectors[  42  ].z;

  return ( checksum );
}

void quicksort_str( char *a, unsigned long n, unsigned long es )
{
  unsigned long j;
  char *pi, *pj, *pn;

  _Pragma( "loopbound min 0 max 8" )
  while ( n > 1 ) {
    if ( n > 10 )
      pi = qs_pivot_strings( a, n );
    else
      pi = a + ( n >> 1 ) * es;

    qs_swap20( a, pi );
    pi = a;
    pn = a + n * es;
    pj = pn;

    _Pragma( "loopbound min 0 max 169" )
    while ( 1 ) {
      _Pragma( "loopbound min 1 max 26" )
      do
        pi += es;
      while ( ( pi < pn ) && QS_STR_LT( pi, a ) );

      _Pragma( "loopbound min 1 max 23" )
      do
        pj -= es;
      while ( ( pj > a ) && QS_STR_GT( pj, a ) );

      if ( pj < pi )
        break;
      qs_swap20( pi, pj );
    }
    qs_swap20( a, pj );
    j = ( pj - a ) / es;
    n = n - j - 1;

    if ( j >= n ) {
      quicksort_str( a, j, es );
      a += ( j + 1 ) * es;
    } else {
      quicksort_str( a + ( j + 1 ) * es, n, es );
      n = j;
    }
  }
}

void quicksort_vec( char *a, unsigned long n, unsigned long es )
{
  unsigned long j;
  char *pi, *pj, *pn;

  _Pragma( "loopbound min 0 max 15" )
  while ( n > 1 ) {
    if ( n > 10 )
      pi = qs_pivot_vectors( a, n );
    else
      pi = a + ( n >> 1 ) * es;

    qs_swap24( a, pi );
    pi = a;
    pn = a + n * es;
    pj = pn;
    double dpiv = qs_dist( a );

    _Pragma( "loopbound min 1 max 250" )
    while ( 1 ) {
      _Pragma( "loopbound min 1 max 51" )
      do
        pi += es;
      while ( ( pi < pn ) && ( !( qs_dist( pi ) > dpiv ) && qs_dist( pi ) != dpiv ) );

      _Pragma( "loopbound min 1 max 27" )
      do
        pj -= es;
      while ( ( pj > a ) && ( qs_dist( pj ) > dpiv ) );

      if ( pj < pi )
        break;

      qs_swap24( pi, pj );
    }

    qs_swap24( a, pj );
    j = ( pj - a ) / es;
    n = n - j - 1;

    if ( j >= n ) {
      quicksort_vec( a, j, es );
      a += ( j + 1 ) * es;
    } else {
      quicksort_vec( a + ( j + 1 ) * es, n, es );
      n = j;
    }
  }
}

void _Pragma ( "entrypoint" ) quicksort_main( void )
{
  _Pragma( "marker recursivecall" )
  _Pragma( "flowrestriction 1*quicksort_str <= 521*recursivecall" )
  quicksort_str( *quicksort_strings, 681, sizeof( char[  20  ] ) );

  _Pragma( "marker recursivecall2" )
  _Pragma( "flowrestriction 1*quicksort_vec <= 650*recursivecall2" )
  quicksort_vec(
    ( char * ) quicksort_vectors, 1000,
    sizeof( struct quicksort_3DVertexStruct ) );
}

